def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the color used for the full-height and full-width dividers.
    divider = None
    for row in grid:
        if row[0] != 0 and all(v == row[0] for v in row):
            divider = row[0]
            break
    if divider is None:
        for c in range(w):
            if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h)):
                divider = grid[0][c]
                break

    row_walls = [r for r in range(h) if all(v == divider for v in grid[r])]
    col_walls = [c for c in range(w) if all(grid[r][c] == divider for r in range(h))]

    def runs(length, walls):
        result, start = [], 0
        wall_set = set(walls)
        for i in range(length):
            if i in wall_set:
                if start < i:
                    result.append(list(range(start, i)))
                start = i + 1
        if start < length:
            result.append(list(range(start, length)))
        return result

    row_groups = runs(h, row_walls)
    col_groups = runs(w, col_walls)

    # The first panel of each panel-row gives that row's output color.
    labels = []
    for rg in row_groups:
        colors = [grid[r][c] for r in rg for c in col_groups[0] if grid[r][c] != 0]
        labels.append(max(set(colors), key=colors.count))

    label_colors = set(labels)

    # Find the distinct-colored pattern cell and record its occupied shape.
    pattern = None
    for ri, rg in enumerate(row_groups):
        for ci, cg in enumerate(col_groups):
            if ci == 0:
                continue
            cells = [(r, c, grid[r][c]) for r in rg for c in cg if grid[r][c] != 0]
            distinctive = [v for _, _, v in cells if v not in label_colors]
            if distinctive:
                color = distinctive[0]
                pattern = {(r - rg[0], c - cg[0])
                           for r, c, v in cells if v == color}
                break
        if pattern is not None:
            break

    # Fallback: use the non-square occupied shape in a non-label panel.
    if pattern is None:
        for rg in row_groups:
            for cg in col_groups[1:]:
                occupied = {(r - rg[0], c - cg[0])
                            for r in rg for c in cg if grid[r][c] != 0}
                if occupied and len(occupied) != 4:
                    pattern = occupied
                    break
            if pattern is not None:
                break

    out = [[0] * w for _ in range(h)]
    for r in row_walls:
        for c in range(w):
            out[r][c] = divider
    for c in col_walls:
        for r in range(h):
            out[r][c] = divider

    for ri, rg in enumerate(row_groups):
        for cg in col_groups:
            for dr, dc in pattern:
                if dr < len(rg) and dc < len(cg):
                    out[rg[dr]][cg[dc]] = labels[ri]

    return out
